import{_ as i,r as t,o as s,c as r,e as o,a as c,s as l}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Image Resizing - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Resize Parameters","slug":"resize-parameters","link":"#resize-parameters","children":[{"level":3,"title":"Available Modes","slug":"available-modes","link":"#available-modes","children":[]}]},{"level":2,"title":"Resize sources","slug":"resize-sources","link":"#resize-sources","children":[]}],"relativePath":"1.x/services/image-resizing.md","filePath":"1.x/services/image-resizing.md"}'),n={name:"1.x/services/image-resizing.md"};function h(p,e,m,g,u,b){const a=t("pre-heading"),d=t("post-heading");return s(),r("div",null,[o(a),e[0]||(e[0]=c("h1",null,"Image Resizing",-1)),o(d),e[1]||(e[1]=l('<blockquote><p><strong>Note</strong>: The image resizing functionality requires a cache driver that persists cache data between requests in order to function, <code>array</code> is not a supported cache driver if you wish to use this functionality.</p></blockquote><h2 id="resize-parameters"><a href="#resize-parameters" class="header-anchor">#</a> Resize Parameters</h2><p>The basic parameters provided to the ImageResizer are <code>(int) $width</code>, <code>(int) $height</code>, and <code>(array) $options</code>.</p><p>If <code>$width</code> or <code>$height</code> is falsey or <code>&#39;auto&#39;</code>, that value is calculated using original image ratio (automatic proportional scaling).</p><p>The following elements are supported in the options array are supported:</p><div class="table"><table tabindex="0"><thead><tr><th>Key</th><th>Description</th><th>Default</th><th>Options</th></tr></thead><tbody><tr><td><code>mode</code></td><td>How the image should be fitted to dimensions</td><td><code>auto</code></td><td><code>exact</code>, <code>portrait</code>, <code>landscape</code>, <code>auto</code>, <code>fit</code>, or <code>crop</code></td></tr><tr><td><code>offset</code></td><td>Offset the crop of the resized image</td><td><code>[0,0]</code></td><td>[left, top]</td></tr><tr><td><code>quality</code></td><td>Quality of the resized image</td><td><code>90</code></td><td><code>0-100</code></td></tr><tr><td><code>sharpen</code></td><td>Amount to sharpen the image</td><td><code>0</code></td><td><code>0-100</code></td></tr></tbody></table></div><h3 id="available-modes"><a href="#available-modes" class="header-anchor">#</a> Available Modes</h3><p>The <code>mode</code> option allows you to specify how the image should be resized. The available modes are as follows:</p><div class="table"><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><code>auto</code></td><td>Automatically choose between <code>portrait</code> and <code>landscape</code> based on the image&#39;s orientation</td></tr><tr><td><code>exact</code></td><td>Resize to the exact dimensions given, without preserving aspect ratio</td></tr><tr><td><code>portrait</code></td><td>Resize to the given height and adapt the width to preserve aspect ratio</td></tr><tr><td><code>landscape</code></td><td>Resize to the given width and adapt the height to preserve aspect ratio</td></tr><tr><td><code>crop</code></td><td>Crop to the given dimensions after fitting as much of the image as possible inside those</td></tr><tr><td><code>fit</code></td><td>Fit the image inside the given maximal dimensions, keeping the aspect ratio</td></tr></tbody></table></div><h2 id="resize-sources"><a href="#resize-sources" class="header-anchor">#</a> Resize sources</h2><p>The available sources that images can be resized from are as follows:</p><ul><li>Plugins</li><li>Themes</li><li>Media Library</li><li>Uploads Directory</li><li>Models that extend the <code>\\October\\Rain\\Database\\Attach\\File</code> model</li></ul><p>Available sources can be extended by listening to the <a href="./../api/system/resizer/getavailablesources.html"><code>system.resizer.getAvailableSources</code> event</a></p>',13))])}const z=i(n,[["render",h]]);export{v as __pageData,z as default};
